const ids = "werk, werk-loop, werk-board, werk-mc-scope, werk-base, werk-v0-seams, werk-loop-tier, visual, werk-chat, werk-write, werk-excerpt, werk-reflink, werk-codeblock, werk-wording, werk-propose-new, werk-contract, werk-dev, werk-hmr, werk-test, pr-wf-paused, align, werk-stack, pr-log, lp-stateless, st-build-steps, st-spec, st-ticket, st-build-ticket, st-build-run, lp-overseer, lp-prod-judge, lp-prod-review, st-validate-heldout, st-build-seam, stages, st-ticket-stories, lp-checks, st-g2-heldout, lp-prod-heldout, lp-trend, vi-board, werk-board-columns, werk-board-control, werk-multichat, werk-mc-fork, werk-mc-split, werk-mc-shared, werk-mc-open, werk-mc-tabs, werk-mc-park, werk-mc-follow, werk-mc-asks, werk-mc-live, st-tier, st-tier-default, st-tier-say, st-tier-escalate".split(", ");
const S = new Set(ids);
const txt = await Bun.file(".werk/log.jsonl").text();
const e = new Map<string,boolean>();
for (const l of txt.split("\n")) { if(!l) continue; const ev = JSON.parse(l);
  if (ev.type==="edge.added"||ev.type==="edge.removed") { const p=ev.payload; if(p.type!=="depends_on")continue; if(!S.has(p.from)||!S.has(p.to))continue; e.set(p.from+" -> "+p.to, ev.type==="edge.added"); } }
for (const [k,v] of e) if (v) console.log(k);
EOF
bun /tmp/edges.ts | sort

cd /Users/eryk.napierala/conductor/workspaces/werk/iqaluit; bun /tmp/edges.ts > /tmp/e.txt; cat > /tmp/chk.ts <<'EOF'
const edges = (await Bun.file("/tmp/e.txt").text()).trim().split("\n").map(l=>l.split(" -> "));
const dir=".werk/tickets/1792366212990/"; const T:any={};
for (let i=1;i<=27;i++){const n=String(i).padStart(2,"0");const t=await Bun.file(dir+n+".md").text();
 const g=(k:string)=>(t.match(new RegExp("^"+k+": ?(.*)$","m"))![1]).split(",").map(s=>s.trim()).filter(Boolean);
 T[i]={cites:g("cites"),bb:g("blocked_by").map(Number)};}
for (const i in T){ const need=new Set<number>();
 for(const c of T[i].cites) for(const [f,to] of edges) if(f===c) for(const j in T) if(+j!==+i && T[j].cites.includes(to)) need.add(+j);
 const missing=[...need].filter(x=>!T[i].bb.includes(x)); const later=[...need].filter(x=>x>+i);
 if(missing.length||later.length) console.log(i,"missing",missing,"later",later);}
EOF
bun /tmp/chk.ts
